import java.util.*;

public class GcBasics {
    // La referencia estatica es un GC root
    static List<String> cache = new ArrayList<>();

    public static void main(String[] args) {
        // Objeto local: vive mientras el metodo este activo
        String temporal = "hello";

        // Objeto sin referencia fuerte: candidato a GC
        new String("olvidado");

        // Sugerir GC (no garantiza ejecucion)
        System.gc();

        // Fuga tipica: agregar sin remover
        for (int i = 0; i < 1_000_000; i++) {
            cache.add("item-" + i);  // nunca se limpia
        }

        // GC roots incluyen:
        // - Thread objects (hilos activos)
        // - Static fields (variables de clase)
        // - JNI references
        // - Synchronized locks (monitors)
        // - Bootstrap classloader objects
    }
}

public class GenerationalDemo {
    public static void main(String[] args) {
        // Objetos cortos-lived: mueren en Eden sin llegar a Survivor
        for (int i = 0; i < 100_000; i++) {
            String temp = "valor-" + i;  // se crea y se descarta
        }

        // Objeto que sobrevive y se promueve a Old
        List<byte[]> longLived = new ArrayList<>();
        for (int i = 0; i < 1000; i++) {
            longLived.add(new byte[1024]);  // permanece en memoria
        }

        // Promocion a Old ocurre cuando:
        // 1. Survivor threshold alcanzado (-XX:MaxTenuringThreshold=15)
        // 2. Objetos grandes van directo a Old
        // 3. Survivor空间 lleno

        // Monitorear con: jstat -gc <pid> 1000
        // columnas: S0C, S1C, EC, OC = capacidad de cada area
    }
}
