        // Shenandoah: concurrencia total con el aplicativo
        // java -XX:+UseShenandoahGC \
        //      -Xmx8g -jar app.jar

        // Simular carga para observar GC:
        List<Object> datos = new ArrayList<>();
        for (int i = 0; i < 10_000; i++) {
            datos.add(new int[1024]);
            if (i % 1000 == 0) {
