public class MemoryLeakDemo {
    // Fuga 1: coleccion estatica que crece sin limite
    static final List<Object> leak = new ArrayList<>();

    // Fuga 2: HashMap sin limpiar claves
    static final Map<String, byte[]> cache = new HashMap<>();

    public static void main(String[] args) {
        // Fuga 1: cada llamada agrega datos que nunca se liberan
        for (int i = 0; i < 100_000; i++) {
            leak.add(new byte[4096]);
        }

        // Fuga 2: claves que nunca se remueven
        for (int i = 0; i < 50_000; i++) {
            cache.put("key-" + i, new byte[2048]);
        }

        // Diagnostico:
