public class ClassLoaderHierarchy {
    public static void main(String[] args) {
        // Ver el classloader de diferentes clases
        ClassLoader appLoader = ClassLoaderHierarchy.class.getClassLoader();
        ClassLoader stringLoader = String.class.getClassLoader();

        System.out.println("App loader: " + appLoader);
        System.out.println("String loader: " + stringLoader); // null = bootstrap

        // Jerarquia: App -> Platform -> Bootstrap
        ClassLoader parent = appLoader;
        while (parent != null) {
            System.out.println(" -> " + parent);
            parent = parent.getParent();
        }
        // Output: AppClassLoader -> PlatformClassLoader -> null (Bootstrap)

        // Bootstrap no es accesible desde Java:
        // ClassLoader bootstrap = null; // concepto, no referencia real

        // Cada clase conoce su loader:
        System.out.println(String.class.getClassLoader()); // null
        System.out.println(java.sql.Date.class.getClassLoader()); // Platform
        System.out.println(ClassLoaderHierarchy.class.getClassLoader()); // App
    }
}

public class LoadingPhases {
    // Fase Initialization: se ejecuta cuando la clase se inicializa
    static {
        System.out.println("Bloque static ejecutado en Initialization");
    }

    static int valor = initStatic();

    static int initStatic() {
        System.out.println("Metodo static para inicializar valor");
        return 42;
    }

    public static void main(String[] args) throws Exception {
        // Class.forName() ejecuta Loading + Linking + Initialization
        Class<?> c1 = Class.forName("LoadingPhases");

        // ClassLoader.loadClass() solo ejecuta Loading (sin initialization)
        Class<?> c2 = ClassLoader.getSystemClassLoader()
            .loadClass("LoadingPhases"); // no ejecuta el bloque static

        // Verificar fases con verbose:
        // java -verbose:class LoadingPhases
        // Muestra cada paso:>Loading, Verification, Preparation, Resolution, <Initialization
    }
}
