import java.io.*;
import java.net.*;

public class ClassEquality {
    public static void main(String[] args) throws Exception {
        // Class.forName: ejecuta Loading + Linking + Initialization
        Class<?> c1 = Class.forName("java.lang.String");

        // loadClass: solo Loading (sin initialization)
        Class<?> c2 = ClassLoader.getSystemClassLoader()
            .loadClass("java.lang.String");

        System.out.println(c1 == c2); // true: mismo loader, misma clase

        // Ejemplo con ClassLoader custom:
        // Dos loaders distintos cargan "com.Foo"
        // -> c1.equals(c2) pero c1 != c2
        // -> son tipos diferentes en instanceof y cast

        // Ejemplo practico de loadClass (carga lazy):
        public class LazyLoader extends ClassLoader {
            public Class<?> cargar(String nombre) throws ClassNotFoundException {
                // Solo carga, no inicializa (sin ejecutar bloques static)
                return findClass(nombre);
            }
        }
    }
}
