public class JitDemo {
    // Este metodo se ejecuta muchas veces -> se vuelve "hot"
    // El JIT lo compila a codigo nativo para mejor rendimiento
    static int sumar(int n) {
        int suma = 0;
        for (int i = 1; i <= n; i++) {
            suma += i;
        }
        return suma;
    }

    public static void main(String[] args) {
        // Primera ejecucion: interpretado
        // Despues de ~10.000 invocaciones: compilado por C1
        // Despues de ~100.000 invocaciones: compilado por C2
        long inicio = System.nanoTime();
        for (int i = 0; i < 200_000; i++) {
            sumar(1000);
        }
        long fin = System.nanoTime();
        System.out.println("Tiempo: " + (fin - inicio) / 1_000_000 + "ms");

        // Diagnosticar compilacion JIT:
        // java -XX:+PrintCompilation -jar app.jar
        // Muestra cuando cada metodo se compila a nativo
    }
}
