import java.lang.ref.WeakReference;
import java.util.WeakHashMap;
import java.util.Map;

public class WeakDemo {
    public static void main(String[] args) {
        // Referencia fuerte: impide recoleccion
        String fuerte = new String("importante");

        // WeakReference: no impide recoleccion
        WeakReference<String> debil = new WeakReference<>(new String("temporal"));
        System.out.println("Antes del GC: " + debil.get()); // "temporal"

        System.gc();
        // Puede que el GC aun no haya corrido, forzar con espera:
        try { Thread.sleep(100); } catch (InterruptedException e) {}
        System.out.println("Despues del GC: " + debil.get()); // null probablemente

        // WeakHashMap: claves se limpian automaticamente
        Map<String, byte[]> cache = new WeakHashMap<>();
        String clave = new String("data");
        cache.put(clave, new byte[1024]);
        System.out.println("Size: " + cache.size()); // 1

        clave = null;  // elimino la unica referencia fuerte a la clave
        System.gc();
        try { Thread.sleep(100); } catch (InterruptedException e) {}
        System.out.println("Size despues de GC: " + cache.size()); // 0
    }
}

import java.lang.ref.SoftReference;
import java.util.HashMap;
import java.util.Map;

public class SoftCache<K, V> {
    private final Map<K, SoftReference<V>> cache = new HashMap<>();
    private final java.util.function.Function<K, V> loader;

    public SoftCache(java.util.function.Function<K, V> loader) {
        this.loader = loader;
    }

    public V get(K key) {
        SoftReference<V> ref = cache.get(key);
        V value = (ref != null) ? ref.get() : null;

        if (value == null) {
            value = loader.apply(key);  // reconstruir si fue recolectado
            cache.put(key, new SoftReference<>(value));
        }
        return value;
    }

    // Ejemplo de uso: cache de imagenes
    // SoftCache<String, Image> imgCache = new SoftCache<>(this::cargarImagen);
    // Image img = imgCache.get("foto.jpg");
    // La imagen permanece en cache mientras haya memoria suficiente
}
