import java.lang.ref.PhantomReference;
import java.lang.ref.Reference;
import java.lang.ref.ReferenceQueue;

public class PhantomDemo {
    static class RecursoNativo {
        private final String nombre;

        RecursoNativo(String nombre) {
            this.nombre = nombre;
            System.out.println("Abriendo recurso: " + nombre);
        }

        void liberar() {
            System.out.println("Liberando recurso: " + nombre);
        }
    }

    static class RecursoRef extends PhantomReference<RecursoNativo> {
        String nombre;

        RecursoRef(RecursoNativo recurso, ReferenceQueue<? super RecursoNativo> queue) {
            super(recurso, queue);
            this.nombre = recurso.nombre;
        }

        void cleanup() {
            System.out.println("Cleanup de: " + nombre);
            // Liberar recursos nativos aqui
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ReferenceQueue<RecursoNativo> queue = new ReferenceQueue<>();
        RecursoNativo recurso = new RecursoNativo("archivo.dat");
        RecursoRef ref = new RecursoRef(recurso, queue);

        recurso = null;  // eliminar referencia fuerte
        System.gc();
        Thread.sleep(100);

        // Verificar si el objeto fue recolectado
        Reference<?> collected = queue.poll();
        if (collected != null) {
            ((RecursoRef) collected).cleanup();
            collected.clear();
        }
    }
}
